::-webkit-scrollbar {
  display: none !important;
}

html,
textarea {
  background: lightgoldenrodyellow;
}

html,
body,
#container {
  height: 100%;
  width: 100%;
  overflow-x: hidden;
  position: relative; /* 親要素を相対位置に設定 */
}

#writebox {
  font-size: large;
  padding: 20px;
  width: 100%;
  height: calc(100% - 70px); /* ボタンの高さを考慮 */
  border: none;
  letter-spacing: 2px;
  color: rgb(27, 77, 63);
  font-family: serif;
  font-weight: bold;
  line-height: 1.69;
  border: none;
  outline: none;
}

#clearbutton {
  position: absolute;
  right: 10px;
  bottom: 10px;
  width: 70px;
  height: 70px;
  background-color: pink;
  border-radius: 50%;
  transition: transform 0.3s; /* 移動時のアニメーションを追加 */
}

@media (max-width: 600px) {
  #clearbutton {
    display: block;
  }
}

@media (min-width: 601px) {
  #clearbutton {
    display: none;
  }
}

/* キーボードが表示されたときの処理 */
@media screen and (max-height: 400px) {
  #clearbutton {
    transform: translateY(-100%); /* ボタンを上に移動 */
  }
}

