@Service
public class SnackService {
    @Autowired
    private SnackMapper snackMapper;

    public List<Snack> searchSnacksWithFilter(String keyword, List<String> filter) {
        // Mapper 인터페이스를 호출하여 데이터 검색
        List<Snack> searchResults = snackMapper.searchSnacks(keyword);

