import { onCleanup } from "solid-js";

const scrollToRight = (element) => {
  if (element) {
    element.scrollLeft = element.scrollWidth;
    const observer = new MutationObserver(() => {
      element.scrollLeft = element.scrollWidth;
    });
    observer.observe(element, { childList: true });
    onCleanup(() => observer.disconnect());
  }
};

