#!/bin/sh
set -e
goal="Fix html encoding in generated prompt"
echo "Plan:"
echo "1. Adjust the loadPromptFile function to decode HTML entities"
echo "2. Add a utility function to decode the HTML entities"

# Step 1: Adjust the loadPromptFile function to decode HTML entities

cat <<EOF > src/prompt/loadPromptFile.js
import fs from 'fs';
import path from 'path';
import ejs from 'ejs';
import { fileURLToPath } from 'url';
import { decodeHtmlEntities } from './decodeHtmlEntities.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const loadPromptFile = async (filePath, templateVars) => {
  try {
    // Try to read the file relative to the current directory
    const rendered = await ejs.renderFile(filePath, templateVars, {async: true});
    return decodeHtmlEntities(rendered);
  } catch (err) {
    // If the file doesn't exist, try reading it from the project root directory
    const rootPath = path.resolve(__dirname, '../../', filePath);
    const rendered = await ejs.renderFile(rootPath, templateVars, {async: true});
    return decodeHtmlEntities(rendered);
  }
};

export { loadPromptFile };
EOF

# Step 2: Add a utility function to decode the HTML entities

cat <<EOF > src/prompt/decodeHtmlEntities.js
function decodeHtmlEntities(encodedString) {
    const textArea = document.createElement('textarea');
    textArea.innerHTML = encodedString;
    return textArea.value;
}

export { decodeHtmlEntities };
EOF

echo "\033[32mDone: $goal\033[0m\n"

