import { onCleanup } from 'solid-js';
import useKeyBindings from './service/useKeyBindings';
import keyBindings from './config/keyBindings';
import NavBar from './components/NavBar';
import PromptCreation from './components/PromptCreation';
import ChangeExecution from './components/ChangeExecution';
import ChangeInspection from './components/ChangeInspection';
import ChangeFinalization from './components/ChangeFinalization';

const App = () => {
  const bindings = keyBindings();
  useKeyBindings(bindings);

  // Ensure that the content always fills the screen vertically
  let containerElement;
  const resizeContent = () => {
    if (containerElement) {
      const vh = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
      containerElement.style.height = `${vh}px`;
    }
  };

  window.addEventListener('resize', resizeContent);
  onCleanup(() => {
    window.removeEventListener('resize', resizeContent);
  });

  return (
    <div 
      ref={containerElement}
      style="display: flex; flex-direction: column; height: 100vh; overflow-y: auto;"
      class="bg-main max-w-desktop lg:max-w-desktop md:max-w-full sm:max-w-full xs:max-w-full mx-auto flex flex-col items-center space-y-8 px-2 sm:px-4 xs:px-4 pb-4"
    >
      <NavBar />
      <PromptCreation />
      <ChangeExecution />
      <ChangeInspection />
      <ChangeFinalization />
    </div>
  );
};

export default App;
EOF

