import React, { useState, useContext } from "react";
import { NavLink } from "react-router-dom";
import { ReactComponent as LogoDE } from 'assets/img/logo.svg';
import { observer } from "mobx-react";
import style from './style.module.scss';
import Button from '../Button/Button';
import Hamburger from '../Hamburger/Hamburger';
import SideNav from '../SideNav';
import ThemeSwitcher from "../ThemeSwitcher";
import { ThemeContext } from "../../themeContext";
import MailchimpSubscribe from "react-mailchimp-subscribe";
import { isMobile } from "react-device-detect";

const url = "https://jobsforit.us21.list-manage.com/subscribe/post?u=9bb02c9224c59d5a48a7cac52&id=9abe4768b0&f_id=00bbc1e1f0";

const CustomForm = ({ status, message, onValidated }) => {
  let email;

  const submit = () =>
    email &&
    email.value.indexOf("@") > -1 &&
    onValidated({
      EMAIL: email.value,
    });

  return (
    <div
      style={{
        background: "#efefef",
        borderRadius: 2,
        padding: 10,
        display: "inline-block"
      }}
    >
      {status === "sending" && <div style={{color: "blue"}}>sending...</div>}
      {status === "error" && (
        <div
          style={{color: "red"}}
          dangerouslySetInnerHTML={{__html: message}}
        />
      )}
      {status === "success" && (
        <div
          style={{
            color: "green",
            fontSize: "1.5em",
            fontWeight: 400,
          }}
          dangerouslySetInnerHTML={{__html: message}}
        />
      )}
      {status !== "success" && (
        <div>
          <input
            style={{
              fontSize: "1.5em",
              padding: 5,
              cursor: 'text'
            }}
            ref={node => (email = node)}
            type="email"
            placeholder=" your email..."
          />
          <button
            style={{
              fontSize: "1.5em",
              userSelect: 'none',
              backgroundColor: '#ff5e26',
              color: '#fff',
              padding: 5,
              border: '0',
              cursor: 'pointer',
              fontWeight: 800,
              display: 'inline-block'
            }}
            onClick={submit}
          >
            Subscribe
          </button>
        </div>
      )
      }
    </div>
  );
};

const TopNav = observer(() => {
  const [showSideNav, setShowSideNav] = useState(false);
  const themeContext = useContext(ThemeContext);

  const sideNavToggleHandler = () => {
    setShowSideNav(prevState => !prevState);
  }

