      <label class="mr-2">Task:</label>
      <select class="w-full dark:bg-dark-emphasize bg-light-emphasize" value={selectedTask()} onChange={e => handleTaskChange(e)}>
        {tasks().map(task => <option value={task}>{task}</option>)}
      </select>
    </div>
  );
};

