  const ignoreContent = ['prompt.yaml', 'prompt.md', 'change.sh', 'node_modules'].join('\n');

  if (existsSync(gitignorePath)) {
    const gitignoreFileContent = readFileSync(gitignorePath, 'utf-8');
    const isNodeModulesIgnored = gitignoreFileContent.split('\n').includes('node_modules');

    if (!isNodeModulesIgnored) {
      appendFileSync(gitignorePath, `\nnode_modules`);
    }

    appendFileSync(gitignorePath, `\n${ignoreContent}`);
