function GetStockData(const Symbol: string; Multiplier: Integer; Timespan: TTimeSpan; FromDate, ToDate: TDateTime; const APIKey: string): TStockDataResponse;
var
  RESTClient: TRESTClient;
  RESTRequest: TRESTRequest;
  RESTResponse: TRESTResponse;
  JSONValue, ResultsValue: TJSONValue;
  StockDataResponse: TStockDataResponse;
  StockDataArray: TStockDataArray;
  ResultsArray: TJSONArray;
  StockData: TStockData;
  I: Integer;
begin
  RESTClient := TRESTClient.Create('https://api.polygon.io');
  RESTRequest := TRESTRequest.Create(nil);
  RESTResponse := TRESTResponse.Create(nil);

  try
    RESTRequest.Client := RESTClient;
    RESTRequest.Response := RESTResponse;
    RESTRequest.Resource := 'v2/aggs/ticker/{symbol}/range/{multiplier}/{timespan}/{from}/{to}';
    RESTRequest.Method := TRESTRequestMethod.rmGET;

    // Set parameters
    RESTRequest.AddParameter('symbol', Symbol, TRESTRequestParameterKind.pkURLSEGMENT);
    RESTRequest.AddParameter('multiplier', IntToStr(Multiplier), TRESTRequestParameterKind.pkURLSEGMENT);
    RESTRequest.AddParameter('timespan', TimeSpanStr[Timespan], TRESTRequestParameterKind.pkURLSEGMENT);
    RESTRequest.AddParameter('from', FormatDateTime('yyyy-mm-dd', FromDate), TRESTRequestParameterKind.pkURLSEGMENT);
    RESTRequest.AddParameter('to', FormatDateTime('yyyy-mm-dd', ToDate), TRESTRequestParameterKind.pkURLSEGMENT);
    RESTRequest.AddParameter('apiKey', APIKey, TRESTRequestParameterKind.pkGETorPOST);

    RESTRequest.Execute;

    if RESTRequest.Response.StatusCode = 200 then
    begin
      JSONValue := TJSONObject.ParseJSONValue(RESTResponse.Content);
      try
        // Extract data from JSON and populate StockDataResponse
        StockDataResponse.Ticker := JSONValue.GetValue<string>('ticker');
        StockDataResponse.QueryCount := JSONValue.GetValue<Integer>('queryCount');
        StockDataResponse.ResultsCount := JSONValue.GetValue<Integer>('resultsCount');
        StockDataResponse.Adjusted := JSONValue.GetValue<Boolean>('adjusted');
        StockDataResponse.Status := JSONValue.GetValue<string>('status');
        StockDataResponse.RequestId := JSONValue.GetValue<string>('request_id');
        StockDataResponse.Count := JSONValue.GetValue<Integer>('count');

        // Populate StockDataArray from 'results' array in JSON
        ResultsValue := JSONValue.GetValue<TJSONValue>('results');
        if ResultsValue is TJSONArray then
        begin
          ResultsArray := ResultsValue as TJSONArray;
          SetLength(StockDataArray, ResultsArray.Count);
          for I := 0 to ResultsArray.Count - 1 do
          begin
            StockData.v := ResultsArray.Items[I].GetValue<Integer>('v');
            StockData.vw := ResultsArray.Items[I].GetValue<Double>('vw');
            StockData.o := ResultsArray.Items[I].GetValue<Double>('o');
            StockData.c := ResultsArray.Items[I].GetValue<Double>('c');
            StockData.h := ResultsArray.Items[I].GetValue<Double>('h');
            StockData.l := ResultsArray.Items[I].GetValue<Double>('l');
            StockData.t := ResultsArray.Items[I].GetValue<Int64>('t');
            StockData.n := ResultsArray.Items[I].GetValue<Integer>('n');
            StockDataArray[I] := StockData;
          end;
        end;
        StockDataResponse.Results := StockDataArray;

        Result := StockDataResponse;

      finally
        JSONValue.Free;
      end;
    end
    else
      raise Exception.CreateFmt('Request failed with status code %d: %s', [RESTRequest.Response.StatusCode, RESTResponse.Content]);

  finally
    RESTResponse.Free;
    RESTRequest.Free;
    RESTClient.Free;
  end;
end;

