ok thank you! so is the following code correct based on your suggestions:

name: Add/Remove Labels

on:
  pull_request_target:
    types: [ opened, closed ]

jobs:
  add_new_contributor_label:
    if: github.event.action == 'opened'
    permissions:
      contents: read
      pull-requests: write
    runs-on: ubuntu-latest
    steps:
      - uses: actions/github-script@v6
        with:
          script: |
            const creator = context.payload.sender.login;
            const opts = github.rest.issues.listForRepo.endpoint.merge({
              ...context.issue,
              creator,
              state: 'all',
            });

            const issues = await github.paginate(opts);

            let isAlreadyContributor = false;

            for (const issue of issues) {
              if (issue.number === context.issue.number) {
                continue;
              }
              if (issue.pull_request && issue.user.login === creator) {
                isAlreadyContributor = true;
                break;
              }
            }

            if (!isAlreadyContributor) {
              await github.rest.issues.addLabels({
                issue_number: context.issue.number,
                owner: context.repo.owner,
                repo: context.repo.repo,
                labels: ['new contributor'],
              });
            }

